package com.jnapanam.sportszone.usermanagement.controller;import com.jnapanam.sportszone.identity.model.*;import com.jnapanam.sportszone.usermanagement.dto.*;import com.jnapanam.sportszone.usermanagement.service.UserManagementService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/admin/users")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN')")public class AdminUserManagementController{private final UserManagementService service;public AdminUserManagementController(UserManagementService s){service=s;}@GetMapping public AdminUserPageResponse search(@RequestParam(required=false)String q,@RequestParam(required=false)UserStatus status,@RequestParam(required=false)RoleName role,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.search(q,status,role,page,size);}@GetMapping("/{id}")public AdminUserDetailResponse detail(@PathVariable UUID id){return service.detail(id);}@PostMapping@ResponseStatus(HttpStatus.CREATED)public AdminUserResponse create(@Valid@RequestBody AdminCreateUserRequest r){return service.create(r);}@PutMapping("/{id}")public AdminUserResponse update(@PathVariable UUID id,@Valid@RequestBody AdminUpdateUserRequest r){return service.update(id,r);}@PatchMapping("/{id}/status")public AdminUserResponse status(Authentication a,@PathVariable UUID id,@Valid@RequestBody UserStatusRequest r){return service.status(id,r,superAdmin(a));}@PatchMapping("/{id}/payment-policy")public AdminUserResponse paymentPolicy(@PathVariable UUID id,@RequestBody PaymentPolicyRequest r){return service.paymentPolicy(id,r);}@PutMapping("/{id}/roles")public AdminUserResponse roles(Authentication a,@PathVariable UUID id,@Valid@RequestBody UserRolesRequest r){if(superAdmin(a)&&UUID.fromString(a.getName()).equals(id)&&!r.roles().contains(RoleName.SUPER_ADMIN))throw new com.jnapanam.sportszone.common.exception.ConflictException("Super administrators cannot remove their own privileged role");return service.roles(id,r,superAdmin(a));}@PostMapping("/{id}/password-reset")@ResponseStatus(HttpStatus.NO_CONTENT)public void reset(Authentication a,@PathVariable UUID id,@Valid@RequestBody AdminPasswordResetRequest r){service.resetPassword(id,r,superAdmin(a));}@PostMapping("/{id}/notes")@ResponseStatus(HttpStatus.CREATED)public UserNoteResponse note(Authentication a,@PathVariable UUID id,@Valid@RequestBody AdminNoteRequest r){return service.note(id,UUID.fromString(a.getName()),r);}@PutMapping("/{id}/tags")public Set<String>tags(@PathVariable UUID id,@Valid@RequestBody UserTagsRequest r){return service.tags(id,r);}@GetMapping("/roles/available")public List<String>roles(){return service.roleNames();}private static boolean superAdmin(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_SUPER_ADMIN"));}}
